  readonly organization: Organization;
  readonly usage: OrganizationUsage;
  readonly memberCount: number;
  readonly projectCount: number;
}

export type OwnershipHandoverStatus =
  | "pending"
  | "accepted"
  | "declined"
  | "canceled"
  | "expired";

/**
 * An offer by the recorded owner to hand the workspace to another member.
 * `expiresAt` is always exactly seven days after `createdAt`; only a
 * `"pending"` handover has no `resolvedAt`.
 */
export interface OwnershipHandover {
  readonly id: string;
  readonly orgId: OrgId;
  readonly fromUserId: UserId;
  readonly toUserId: UserId;
  readonly status: OwnershipHandoverStatus;
  readonly expiresAt: IsoTimestamp;
  readonly createdAt: IsoTimestamp;
  readonly resolvedAt: IsoTimestamp | null;
}

