function isHandoverExpired(
  handover: OwnershipHandover,
  now: Date = new Date(),
): boolean {
  return new Date(handover.expiresAt).getTime() <= now.getTime();
}

/**
 * Only the recorded owner — `organization.ownerId`, not merely a member who
 * happens to hold the `owner` role — may offer or withdraw a handover.
 */
function assertRecordedOwner(actor: Actor, org: Organization): void {
  assertCan(actor, "org:manage_ownership", orgResource(org.id));

  if (actor.userId !== org.ownerId) {
    throw new PermissionDeniedError("org:manage_ownership", {
      allowed: false,
      action: "org:manage_ownership",
      resourceKind: "organization",
      reason: "denied_by_role",
    });
  }
}

/**
 * Offers the workspace to another active member. Refused with
 * `OwnershipHandoverError` for a self-offer or a second offer while one is
 * open (a lapsed offer does not count as open and is expired in passing).
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  if (toUserId === actor.userId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const existing = await handoverRepo.findPendingByOrg(orgId);
  if (existing) {
    if (!isHandoverExpired(existing)) {
      throw new OwnershipHandoverError("pending_exists");
    }
    await handoverRepo.resolveHandover(
      existing.id,
      "expired",
      toIsoTimestamp(new Date()),
    );
  }

  const createdAt = toIsoTimestamp(new Date());
  const expiresAt = toIsoTimestamp(new Date(Date.now() + HANDOVER_TTL_MS));

  const handover = await handoverRepo.insertHandover(
    orgId,
    actor.userId,
    toUserId,
    createdAt,
    expiresAt,
  );

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You've been offered this workspace",
    body: `${actor.userId} offered you ownership of this workspace`,
    href: "/settings/organization",
    actorId: actor.userId,
  });

  return handover;
}

/**
 * Resolves to the open offer, or `null` if none is open — a lapsed offer is
 * expired in passing and reported as absent.
 */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "member:read", orgResource(orgId));

  const pending = await handoverRepo.findPendingByOrg(orgId);
  if (!pending) return null;

  if (isHandoverExpired(pending)) {
    await handoverRepo.resolveHandover(
      pending.id,
      "expired",
      toIsoTimestamp(new Date()),
    );
    return null;
  }

  return pending;
}

/** The withdrawal; only the recorded owner may call it, and only while open. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  const pending = await handoverRepo.findPendingByOrg(orgId);
  if (!pending) throw new OwnershipHandoverError("nothing_pending");

  const now = toIsoTimestamp(new Date());
  if (isHandoverExpired(pending)) {
    await handoverRepo.resolveHandover(pending.id, "expired", now);
    throw new OwnershipHandoverError("expired");
  }

  return handoverRepo.resolveHandover(pending.id, "canceled", now);
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const pending = await handoverRepo.findPendingByOrg(orgId);
  if (!pending || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  const now = toIsoTimestamp(new Date());
  if (isHandoverExpired(pending)) {
    await handoverRepo.resolveHandover(pending.id, "expired", now);
    throw new OwnershipHandoverError("expired");
  }

  return handoverRepo.resolveHandover(pending.id, "declined", now);
}

/**
 * Acceptance: the accepting member becomes the recorded owner and takes the
 * `owner` role; the previous owner steps down to `admin` if they still hold
 * `owner` at that moment. The new owner is promoted before the old one is
 * demoted, so the workspace never has zero owners in between. Everything
 * published here is on behalf of the accepting member.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);

  const pending = await handoverRepo.findPendingByOrg(orgId);
  if (!pending || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  const now = toIsoTimestamp(new Date());
  if (isHandoverExpired(pending)) {
    await handoverRepo.resolveHandover(pending.id, "expired", now);
    throw new OwnershipHandoverError("expired");
  }

  const toMember = requireFound(
    await memberRepo.findMember(orgId, pending.toUserId),
    "Member",
    pending.toUserId,
  );
  const fromMember = await memberRepo.findMember(orgId, pending.fromUserId);

  if (toMember.role !== "owner") {
    const updated = await memberRepo.updateMemberRole(orgId, toMember.id, "owner");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: updated.id,
      from: toMember.role,
      to: updated.role,
    });
  }

  if (fromMember && fromMember.role === "owner") {
    const updated = await memberRepo.updateMemberRole(orgId, fromMember.id, "admin");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: updated.id,
      from: fromMember.role,
      to: updated.role,
    });
  }

  const updatedOrg = await orgRepo.transferOwner(orgId, pending.toUserId);

  await handoverRepo.resolveHandover(pending.id, "accepted", now);

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: pending.fromUserId,
    toUserId: pending.toUserId,
  });

  return updatedOrg;
}

/**
 * If either side of an open offer leaves the workspace, the offer is
 * withdrawn automatically. Self-registering at module load, the same way
 * `notification-service`'s fan-out is — this hub has no other entry point.
 */
let handoverListenersRegistered = false;

function registerHandoverListeners(): void {
  if (handoverListenersRegistered) return;
  handoverListenersRegistered = true;

  subscribe("member.removed", async (payload) => {
    const pending = await handoverRepo.findPendingByOrg(payload.orgId);
    if (!pending) return;

    if (pending.fromUserId === payload.userId || pending.toUserId === payload.userId) {
      await handoverRepo.resolveHandover(
        pending.id,
        "canceled",
        toIsoTimestamp(new Date()),
      );
    }
  });
}

registerHandoverListeners();

