 * Acceptance: the accepting member becomes the recorded owner and takes the
 * `owner` role; the previous owner steps down to `admin` if they still hold
 * `owner` at that moment. The new owner is promoted before the old one is
 * demoted, so the workspace never has zero owners in between. Everything
 * published here is on behalf of the accepting member.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);

  const pending = await handoverRepo.findPendingByOrg(orgId);
  if (!pending || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  const now = toIsoTimestamp(new Date());
  if (isHandoverExpired(pending)) {
    await handoverRepo.resolveHandover(pending.id, "expired", now);
    throw new OwnershipHandoverError("expired");
  }

  const toMember = requireFound(
    await memberRepo.findMember(orgId, pending.toUserId),
    "Member",
    pending.toUserId,
  );
  const fromMember = await memberRepo.findMember(orgId, pending.fromUserId);

  if (toMember.role !== "owner") {
    const updated = await memberRepo.updateMemberRole(orgId, toMember.id, "owner");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: updated.id,
      from: toMember.role,
      to: updated.role,
    });
  }

  if (fromMember && fromMember.role === "owner") {
    const updated = await memberRepo.updateMemberRole(orgId, fromMember.id, "admin");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: updated.id,
      from: fromMember.role,
      to: updated.role,
    });
  }

  const updatedOrg = await orgRepo.transferOwner(orgId, pending.toUserId);

  await handoverRepo.resolveHandover(pending.id, "accepted", now);

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: pending.fromUserId,
    toUserId: pending.toUserId,
  });

  return updatedOrg;
}

/**
 * If either side of an open offer leaves the workspace, the offer is
 * withdrawn automatically. Self-registering at module load, the same way
 * `notification-service`'s fan-out is — this hub has no other entry point.
 */
let handoverListenersRegistered = false;

function registerHandoverListeners(): void {
  if (handoverListenersRegistered) return;
  handoverListenersRegistered = true;

  subscribe("member.removed", async (payload) => {
    const pending = await handoverRepo.findPendingByOrg(payload.orgId);
    if (!pending) return;

    if (pending.fromUserId === payload.userId || pending.toUserId === payload.userId) {
      await handoverRepo.resolveHandover(
        pending.id,
        "canceled",
        toIsoTimestamp(new Date()),
      );
    }
  });
}

registerHandoverListeners();

