  assertOrgScope(actor, orgId);

  const pending = await handoverRepo.findPendingByOrg(orgId);
  if (!pending || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  const now = toIsoTimestamp(new Date());
  if (isHandoverExpired(pending)) {
    await handoverRepo.resolveHandover(pending.id, "expired", now);
    throw new OwnershipHandoverError("expired");
  }

  const toMember = requireFound(
    await memberRepo.findMember(orgId, pending.toUserId),
    "Member",
    pending.toUserId,
  );
  const fromMember = await memberRepo.findMember(orgId, pending.fromUserId);

  if (toMember.role !== "owner") {
    const updated = await memberRepo.updateMemberRole(orgId, toMember.id, "owner");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: updated.id,
      from: toMember.role,
