import * as orgRepo from "@/server/repositories/organization-repository";
import * as orgService from "@/server/services/organization-service";
import * as memberService from "@/server/services/member-service";
import { createTenant, useTemporaryDatabase } from "../../tests/server/_support/fixtures";
import type { Tenant } from "../../tests/server/_support/fixtures";

let cleanup: () => void;

describe("ownership handover smoke", () => {
  beforeAll(async () => {
    cleanup = await useTemporaryDatabase();
  });
  afterAll(() => cleanup());

  it("full accept flow transfers role, ownerId, events, and billing access", async () => {
    const tenant: Tenant = await createTenant("handover-smoke", "growth");

    // non-recorded-owner (even with owner role) cannot initiate
    const adminMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    if (!adminMember) throw new Error("missing");
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: adminMember.id,
      role: "owner",
    });
    await expect(
      orgService.initiateOwnershipHandover(
        { ...tenant.actors.admin, role: "owner" },
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    // demote admin back for cleanliness
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: adminMember.id,
      role: "admin",
    });

    // self offer refused
    await expect(
      orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.owner),
    ).rejects.toMatchObject({ reason: "self" });

    // offer to viewer (who holds a low role)
    const offer = await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );
    expect(offer.status).toBe("pending");

    // second offer refused
    await expect(
      orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).rejects.toMatchObject({ reason: "pending_exists" });

    // wrong actor cannot accept
    await expect(
      orgService.acceptOwnershipHandover(tenant.actors.member, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    const roleEvents: unknown[] = [];
    const off1 = subscribe("member.role_changed", (p) => roleEvents.push(p));
    let transferEvent: unknown = null;
    const off2 = subscribe("organization.ownership_transferred", (p) => {
      transferEvent = p;
    });

    const updatedOrg = await orgService.acceptOwnershipHandover(tenant.actors.viewer, tenant.org.id);
    off1();
    off2();

    expect(updatedOrg.ownerId).toBe(tenant.userIds.viewer);
    expect(transferEvent).toMatchObject({
      fromUserId: tenant.userIds.owner,
      toUserId: tenant.userIds.viewer,
      actorId: tenant.userIds.viewer,
    });
    expect(roleEvents).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ from: "viewer", to: "owner" }),
        expect.objectContaining({ from: "owner", to: "admin" }),
      ]),
    );

    const viewerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    const ownerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    expect(viewerMember?.role).toBe("owner");
    expect(ownerMember?.role).toBe("admin");

    // pending is gone now
    expect(await orgService.getPendingOwnershipHandover(tenant.actors.viewer, tenant.org.id)).toBeNull();

    // old owner (now admin) can be removed like any admin
    if (!ownerMember) throw new Error("missing");
    await memberService.removeMember(
      { userId: tenant.userIds.viewer, orgId: tenant.org.id, role: "owner" },
      { orgId: tenant.org.id, memberId: ownerMember.id },
    );
    const removed = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    expect(removed).toBeNull();
  });

  it("expiry, decline, cancel, and auto-withdraw-on-removal", async () => {
    const tenant: Tenant = await createTenant("handover-smoke-2", "growth");

    const offer = await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );

    // decline
    const declined = await orgService.declineOwnershipHandover(tenant.actors.member, tenant.org.id);
    expect(declined.status).toBe("declined");
    await expect(
      orgService.declineOwnershipHandover(tenant.actors.member, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    // new offer, then cancel
    await orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.admin);
    const canceled = await orgService.cancelOwnershipHandover(tenant.actors.owner, tenant.org.id);
    expect(canceled.status).toBe("canceled");
    await expect(
      orgService.cancelOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    // offer again, then remove offered member -> auto withdrawn
    await orgService.initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.viewer);
    const viewerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!viewerMember) throw new Error("missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewerMember.id,
    });
    expect(await orgService.getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id)).toBeNull();
    void offer;
  });
});

